#' Write an R script that reproduces the analysis done in the app
#' @param params list with monitor (ethoscope or dam), result_dir, the scoring parameters and the binning parameters
#' @return character, the script
#' @noRd
reproducibility_script <- function(dataset_name, params) {
  conf <- fslretho_conf()
  scoring <- params$scoring
  sd <- !is.null(scoring$intervals)
  dam <- identical(params$monitor, "dam")
  fmt <- function(x) deparse(x)

  lines <- c(
    "# Script generated by FSLRetho to reproduce the analysis of",
    sprintf("# %s", dataset_name),
    "#",
    "# The analysis uses the versions of the rethomics packages kept at https://github.com/shaliulab",
    "# Install them with: remotes::install_github('shaliulab/fslretho@v3')",
    "library(data.table)",
    "library(ggplot2)",
    "library(behavr)",
    "library(ggetho)",
    "",
    "metadata_path <- 'PATH/TO/YOUR/metadata.csv'",
    "",
    "## ---- Read and check the metadata",
    "metadata <- fslretho::read_metadata(metadata_path)",
    sprintf("problems <- fslretho::check_metadata(metadata, result_dir = %s)", fmt(params$result_dir)),
    "print(problems)",
    "stopifnot(!any(problems$level == 'error'))",
    if (dam) c(
      sprintf(
        "metadata <- damr::link_dam_metadata(fslretho::load_metadata(metadata_path), result_dir = %s)",
        fmt(params$result_dir)
      ),
      "",
      "## ---- Load and score the data (sleep annotation of DAM beam crosses)",
      sprintf("dt <- damr::load_dam(metadata, FUN = sleepr::sleep_dam_annotation, min_time_immobile = %s)", fmt(scoring$min_time_immobile))
    ) else c(
    sprintf(
      "metadata <- scopr::link_ethoscope_metadata(fslretho::load_metadata(metadata_path), result_dir = %s)",
      fmt(params$result_dir)
    ),
    "",
    "## ---- Load and score the data (sleep annotation)",
    "dt <- scopr::load_ethoscope(",
    "  metadata = metadata,",
    "  # take the reference hour (ZT0) of each fly from the metadata",
    "  reference_hour = NA,",
    sprintf("  cache = %s,", fmt(conf$scopr$folders$cache$path)),
    "  FUN = sleepr::sleep_annotation,",
    sprintf("  velocity_correction_coef = %s,", fmt(scoring$velocity_correction_coef)),
    sprintf("  min_time_immobile = %s,", fmt(scoring$min_time_immobile)),
    sprintf("  time_window_length = %s,", fmt(scoring$time_window_length)),
    if (!is.null(scoring$masking_duration)) sprintf("  masking_duration = %s,", fmt(scoring$masking_duration)),
    if (sd) c(
      "  # different scoring parameters while the SD is running",
      sprintf("  velocity_correction_coef_sd = %s,", fmt(scoring$velocity_correction_coef_sd)),
      sprintf("  min_time_immobile_sd = %s,", fmt(scoring$min_time_immobile_sd)),
      sprintf("  time_window_length_sd = %s,", fmt(scoring$time_window_length_sd)),
      if (!is.null(scoring$masking_duration_sd)) sprintf("  masking_duration_sd = %s,", fmt(scoring$masking_duration_sd)),
      "  intervals = list(interval_sd = 'SD'),"
    ),
    sprintf("  curate = %s", fmt(scoring$curate)),
    ")"
    ),
    "",
    "## ---- Fraction of time asleep in each bin",
    "binned <- behavr::bin_apply_all(",
    "  dt, y = 'asleep', x = 't',",
    sprintf("  x_bin_length = behavr::mins(%s),", fmt(params$summary_time_window)),
    sprintf("  FUN = %s", c(mean = "mean", median = "stats::median", max = "max", min = "min")[[params$summary_FUN]]),
    ")",
    "",
    "## ---- Plot",
    "gg <- ggplot(behavr::rejoin(binned), aes(x = t, y = asleep)) +",
    "  ggetho::geom_pop_etho() +",
    "  ggetho::stat_ld_annotations(color = NA, height = 1, alpha = 0.2) +",
    "  ggetho::scale_x_hours() +",
    "  facet_wrap('id')",
    "print(gg)",
    "",
    "data.table::fwrite(behavr::rejoin(binned), 'binned_dataset.csv')",
    "ggplot2::ggsave('plot.png', gg, height = 10, width = 20)"
  )
  paste(lines, collapse = "\n")
}

reproducibilityModuleUI <- function(id) {
  ns <- NS(id)
  tagList(
    downloadButton(ns("download"), "Download script"),
    verbatimTextOutput(ns("script"))
  )
}

#' @param dataset the loaded dataset
#' @param params reactive list with result_dir, scoring, summary_time_window and summary_FUN
#' @noRd
reproducibilityModuleServer <- function(id, dataset, params) {
  moduleServer(
    id,
    function(input, output, session) {
      script <- reactive({
        req(dataset$data)
        reproducibility_script(dataset$name, params())
      })
      output$script <- renderText(script())
      output$download <- downloadHandler(
        filename = function() paste0(dataset_basename(dataset$name), "-analysis.R"),
        content = function(file) writeLines(script(), file)
      )
    }
  )
}
